import json,hashlib
from pathlib import Path
from datetime import datetime
p=json.loads(Path('input/packet.json').read_text()); a=json.loads(Path('input/authoritative-research.json').read_text()); idx=json.loads(Path('input/input-index.json').read_text())
print('本次读取文件索引绑定核验')
read_paths=['input/identity.json','input/article.md','input/packet.json','input/authoritative-research.json','input/research-handoff.md']
for entry in idx['files']:
 if entry['path'] in read_paths:
  raw=Path(entry['path']).read_bytes()
  print(entry['path'],len(raw)==entry['bytes'],hashlib.sha256(raw).hexdigest()==entry['sha256'])
print('handoff text matches authority:',Path('input/research-handoff.md').read_text().strip()==a['authoring_note']['text'].strip())
f=p['facts']['own']; price=f['price_observations'][0]; industry=next(x for x in f['industry_observations'] if x['group_code']=='801086.SI'); rows=f['equity_daily']; bydate={x['trade_date']:x for x in rows}
print('复算：收益沿用既有复权派生；前15日由20日和后5日拆分')
for key,val in {
 '5日收益%':price['return_5d']*100,
 '3日收益%':price['return_3d']*100,
 '前15日收益%':((1+price['return_20d'])/(1+price['return_5d'])-1)*100,
 '最大日后四日收益%':price['return_after_largest_positive_day_5d']*100,
 '5日超行业百分点':(price['return_5d']-industry['equal_weight_return_5d'])*100,
 '3日超行业百分点':(price['return_3d']-industry['equal_weight_return_3d'])*100,
 '5日上涨成员数':industry['breadth_5d']*industry['horizon_observed_member_count_5d'],
 '3日上涨成员数':industry['breadth_3d']*industry['horizon_observed_member_count_3d']
}.items(): print(key,val)
for start,end in [('2026-08-03','2026-08-31'),('2026-08-24','2026-09-11')]:
 w=[x for x in rows if start<=x['trade_date']<=end]
 print('价格窗口',start,end,'n',len(w))
 for key in ['close','high']:
  v=max(w,key=lambda x:x[key]);print('max',key,v[key],v['trade_date'])
print('历史价位归一依据：authoring_note/source_refs/13载明相关历史及形成日因子均5.696。')
for level in [39.20,39.23]:print('旧高距38.35 %',level,(level/38.35-1)*100)
print('20%观察价',38.35*1.2)
print('最后5日成交额亿元、收盘、available_at')
for x in rows[-5:]:print(x['trade_date'],x['amount']/1e8,x['close'],x['available_at'])
print('全部最后5日收盘抬高',all(rows[j]['close']>rows[j-1]['close'] for j in range(len(rows)-5,len(rows))))
print('最后5日成交额递增',all(rows[j]['amount']>rows[j-1]['amount'] for j in range(len(rows)-4,len(rows))))
inc={x['report_period']:x for x in f['income_statement']}; cash={x['report_period']:x for x in f['cash_flow']}
h1=inc['2026-06-30']; prev=inc['2025-06-30']; q1=inc['2026-03-31']
for label,val in {
 '归母亿元':h1['n_income_attr_p']/1e8,
 '归母同比%':(h1['n_income_attr_p']/prev['n_income_attr_p']-1)*100,
 '现金流亿元':cash['2026-06-30']['n_cashflow_act']/1e8,
 '现金流同比%':(cash['2026-06-30']['n_cashflow_act']/cash['2025-06-30']['n_cashflow_act']-1)*100,
 'H1减Q1收入亿元':(h1['revenue']-q1['revenue'])/1e8,
 'H1减Q1归母亿元':(h1['n_income_attr_p']-q1['n_income_attr_p'])/1e8
}.items():print(label,val)
for x in f['main_business']:
 if x['report_period']=='2026-06-30' and x['bz_item'] in ['显示材料','半导体材料']:
  print(x['bz_item'],'亿元',x['bz_sales']/1e8,'占总收入%',x['bz_sales']/h1['revenue']*100)
for x in p['comparisons']['items'][:2]:
 z=x['facts']['price_observations'][0];print(x['name'],'5日%',z['return_5d']*100,'5日超行业百分点',z['relative_industry_return_5d']*100,'涨停贡献',z['limit_up_return_contribution_5d'])
print('文章行号')
for i,line in enumerate(Path('input/article.md').read_text().splitlines(),1):
 if line:print(i,line)
PY"

